import { stdout } from std.io;
final class Seal {
    construct() { }
    name(): String { return "seal"; }
}
class Base {
    construct() { }
    final id(): Int32 { return 1; }
    other(): Int32 { return 2; }
}
class Child extends Base {
    construct() { super(); }
    #override other(): Int32 { return 3; }
}
fn main(): Void {
    stdout.println(Seal().name());
    inmut c = Child();
    stdout.println(c.id() + c.other());
}
